questionvariables.text:
/*Defining the question*/
var_theta:Theta;
coeff_tcubed:rand(3)+1;/*first constant*/
coeff_tsquared:rand_with_prohib(3,9,[0,1]); /*second constant*/
aa:rand(3)+2;
const:aa^2;/*third constant*/
num:rand([3,5]);/*power of function in the bracket*/
power:num/2;
coef: (aa/sqrt(coeff_tsquared))*sec(Theta)
dif_coef:diff(coef,Theta);
func:(coeff_tcubed*t^3*(coeff_tsquared*t^2-const)^power); /*question expression*/


/*worked solution*/
expr1:(coeff_tsquared*t^2-const)^power;
expr2:sqrt((coeff_tsquared*t^2-const))^num;
expr3:sqrt(const*sec^2-const)^num;
expr4: (coeff_tsquared*t^2-const)^(1/2);
expr5: (sqrt(const)^num)*(tan(Theta)^num);
expr6: ev(expr5^(1/num)),simp;
expr7_a: coeff_tcubed*t^3*(sqrt(const)^num)*(tan(var_theta))^num*dif_coef;
expr7: ev(expr7_a,t=coef),simp;
expr7_b: ev(expr7/sec(Theta)^2),simp;
expr8: subst(tan(Theta)^2+1,sec(Theta)^2,expr7_b);
expr9: expand(expr8);
expr10: subst(u,tan(Theta),expr9);
expr11:int(expr10,u)+c;
expr12: subst(tan(Theta),u,expr11);
expr_tan: expr4/sqrt(const);
expr13: subst(expr_tan,tan(Theta),expr12);



/*model answer*/
ta: expr13;

feedbackvariables.text:
/*node 1:checking for correcting answers*/

/*node 2:Failing to add a constant of integration*/
mistake_1:int(func,t);

/*node 3:Differentiating instead of integrating*/
mistake_2:diff(func,t)+c;

/*node 4:Not replacing back the value of u*/
mistake_3:int((u^8-u^6),u)+c;
